head.script:

scwin.onpageload = function() {
	tac_layout.setContentsHeight(500);
};

scwin.onpageunload = function() {

};


scwin.btn_menuOpen_onclick = function(e) {
	var menuId = "A00001";
	var menuNm = "업무화면1";
	var menuUrl = "tabControl_processMsgFrame_processMsgSize_WESD-971_(WSQ-4940)_tab1.xml";		

	var tabObj = { 
		closable		: true,	
		openAction	: "exist",	
		label			: menuNm 
	};

	var contObj = {
		frameMode	: "wframePreload",
		scope			: true,
		src			: menuUrl,
		alwaysDraw	: false,
		title			: menuNm,
		dataObject : { 
			type	: "json", 
			name	: "param", 
			data	: {}
		}
	};

	//content 탭 생성 (생성 탭에 포커스는 별도)  
	var result = tac_layout.addTab(menuId, tabObj, contObj);

	//동일 menuId 의 화면을 new로 생성 할수 있기에, 생성된 tab select 처리 필요함
	//var tabIndex = tac_layout.getTabIndex( result );
	//tac_layout.setSelectedTabIndex( tabIndex );		
};
